/* ============================================================
   App.css — DebugFlow light developer-tool theme (v3)
   White / off-white · Deep blue · Near-black
   ============================================================ */

/* ── CSS Variables ─────────────────────────────────────────── */
:root {
  /* Backgrounds */
  --bg:           #f8f9fb;
  --bg-panel:     #ffffff;
  --bg-surface:   #f3f4f6;
  --bg-code:      #f6f8fa;
  --bg-header:    #0f1b2d;

  /* Borders */
  --border:        #e1e4e8;
  --border-subtle: #eaecef;
  --border-focus:  #2563eb;

  /* Text */
  --text:          #1a1f2e;
  --text-muted:    #6b7280;
  --text-heading:  #0f1b2d;
  --text-on-dark:  #e8edf5;
  --text-muted-on-dark: #94a3b8;

  /* Accent — deep blue */
  --accent:        #2563eb;
  --accent-dark:   #1d4ed8;
  --accent-light:  #eff6ff;
  --accent-border: #bfdbfe;

  /* Status */
  --green:         #16a34a;
  --green-bg:      #f0fdf4;
  --green-border:  #bbf7d0;
  --red:           #dc2626;
  --red-bg:        #fef2f2;
  --red-border:    #fecaca;
  --yellow:        #b45309;
  --yellow-bg:     #fffbeb;
  --yellow-border: #fde68a;

  /* Diff */
  --diff-add-bg:   rgba(22, 163, 74, 0.08);
  --diff-del-bg:   rgba(220, 38, 38, 0.08);
  --diff-hunk:     #2563eb;

  /* Typography */
  --font-sans:  "Inter", -apple-system, "Segoe UI", system-ui, sans-serif;
  --font-mono:  "JetBrains Mono", "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

  /* Geometry */
  --radius:     5px;
  --radius-lg:  8px;
  --radius-xl:  10px;
  --shadow-sm:  0 1px 2px rgba(15, 27, 45, 0.06), 0 1px 4px rgba(15, 27, 45, 0.04);
  --shadow-md:  0 4px 12px rgba(15, 27, 45, 0.10);
  --transition: 0.13s ease;
}

/* ── Reset / Base ───────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 15px;
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.6;
  min-height: 100vh;
}

/* Visually hidden helper for screen-reader labels */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Header ─────────────────────────────────────────────────── */
.app-header {
  background: var(--bg-header);
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding: 0 2rem;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 1px 0 rgba(0,0,0,0.15), 0 2px 8px rgba(0,0,0,0.12);
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 1rem;
}

/* CSS-only logo mark — refined </> code bracket */
.header-logo-wrap {
  width: 40px;
  height: 40px;
  border-radius: 9px;
  background: rgba(37, 99, 235, 0.15);
  border: 1px solid rgba(37, 99, 235, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

/* The </> text mark */
.header-logo-mark {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: #93c5fd;
  letter-spacing: -0.05em;
  line-height: 1;
  user-select: none;
}

/* Red breakpoint dot overlay */
.header-logo-wrap::after {
  content: '';
  position: absolute;
  top: 6px;
  right: 6px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #f87171;
}

.header-text {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.header-title {
  font-size: 1.2rem;
  font-weight: 700;
  color: #f1f5f9;
  letter-spacing: -0.03em;
  line-height: 1.15;
}

.header-tagline {
  font-size: 0.67rem;
  color: var(--text-muted-on-dark);
  letter-spacing: 0.12em;
  line-height: 1.2;
  text-transform: uppercase;
  font-weight: 400;
}

/* Backend status — understated, right-aligned */
.backend-status {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.73rem;
  font-weight: 500;
  padding: 0.28rem 0.7rem;
  border-radius: var(--radius);
  border: 1px solid rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.06);
  color: var(--text-muted-on-dark);
  transition: border-color var(--transition), color var(--transition);
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.backend-status--online  .status-dot { background: #4ade80; }
.backend-status--offline .status-dot { background: #f87171; }
.backend-status--checking .status-dot { background: #fbbf24; animation: pulse 1.4s ease infinite; }

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

.backend-status--online  { color: #86efac; border-color: rgba(74, 222, 128, 0.25); }
.backend-status--offline { color: #fca5a5; border-color: rgba(248, 113, 113, 0.3); }

/* ── Main layout ────────────────────────────────────────────── */
.app-main {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem 2rem 5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* Primary workspace — two-column input row */
.input-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
  align-items: start;
}

@media (max-width: 860px) {
  .app-main { padding: 1.25rem 1rem 3rem; }
  .input-row { grid-template-columns: 1fr; }
}

/* ── Panels ─────────────────────────────────────────────────── */
.panel {
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 1.25rem 1.5rem 1.4rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  box-shadow: var(--shadow-sm);
}

/* Input workspace panels — left rule */
.panel--code-input {
  border-left: 3px solid var(--accent);
}

.panel--error-input {
  border-left: 3px solid var(--red);
}

/* Result stage panels — distinct from input panels via top border */
.panel--result {
  border-top: 2px solid var(--accent);
  background: var(--bg-panel);
}

/* Test runner final stage */
.panel--verify {
  border-top: 2px solid var(--green);
  background: var(--bg-panel);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  min-height: 28px;
}

.panel-subheader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
}

/* Panel section labels — small, uppercase, muted */
.panel-title {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.panel-title::before {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--border);
  flex-shrink: 0;
}

.panel--code-input  .panel-title::before { background: var(--accent); opacity: 0.8; }
.panel--error-input .panel-title::before { background: var(--red); opacity: 0.7; }
.panel--result      .panel-title::before { background: var(--accent); opacity: 0.8; }
.panel--verify      .panel-title::before { background: var(--green); opacity: 0.8; }

/* Result panel titles are slightly more prominent */
.panel-title--lg {
  font-size: 0.82rem;
  color: var(--text-heading);
  letter-spacing: 0.05em;
}

.panel-actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  flex-wrap: wrap;
}

.panel-hint {
  font-size: 0.75rem;
  color: var(--text-muted);
  line-height: 1.4;
}

.panel-footer {
  margin-top: 0.15rem;
  padding-top: 0.9rem;
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Buttons ─────────────────────────────────────────────────── */
.btn {
  cursor: pointer;
  border: 1px solid transparent;
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 500;
  padding: 0.45rem 1rem;
  transition: background var(--transition), border-color var(--transition),
              color var(--transition), box-shadow var(--transition),
              transform var(--transition);
  white-space: nowrap;
  line-height: 1.25;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.btn:not(:disabled):active { transform: translateY(1px); }

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* Primary — strong filled blue, main CTA */
.btn--primary {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent-dark);
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(37, 99, 235, 0.2);
}
.btn--primary:not(:disabled):hover {
  background: var(--accent-dark);
  border-color: #1e40af;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.25);
}

/* Secondary — subtle bordered, helper actions */
.btn--secondary {
  background: var(--bg-panel);
  color: var(--text);
  border-color: var(--border);
}
.btn--secondary:not(:disabled):hover {
  background: var(--bg-surface);
  border-color: var(--accent-border);
  color: var(--accent);
}

/* Ghost — transparent low-emphasis */
.btn--ghost {
  background: transparent;
  color: var(--text-muted);
  border-color: transparent;
}
.btn--ghost:not(:disabled):hover {
  color: var(--text);
  background: var(--bg-surface);
  border-color: var(--border);
}

/* Accent-green — Apply Fix */
.btn--accent {
  background: var(--green-bg);
  color: var(--green);
  border-color: var(--green-border);
  font-weight: 600;
}
.btn--accent:not(:disabled):hover {
  background: #dcfce7;
  border-color: #86efac;
  box-shadow: 0 1px 4px rgba(22, 163, 74, 0.15);
}

/* Run tests — same solid blue as primary */
.btn--run {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent-dark);
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(37, 99, 235, 0.2);
}
.btn--run:not(:disabled):hover {
  background: var(--accent-dark);
  border-color: #1e40af;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.25);
}

.btn--sm {
  font-size: 0.75rem;
  padding: 0.28rem 0.65rem;
  border-radius: 4px;
}

/* Chip — compact error-preset selectors */
.btn--chip {
  font-size: 0.73rem;
  font-weight: 500;
  padding: 0.22rem 0.65rem;
  border-radius: 999px;
  background: var(--bg-surface);
  color: var(--text-muted);
  border-color: var(--border);
  letter-spacing: 0.01em;
}
.btn--chip:not(:disabled):hover {
  color: var(--red);
  border-color: var(--red-border);
  background: var(--red-bg);
}

.btn--lg {
  font-size: 0.9rem;
  padding: 0.58rem 1.35rem;
  border-radius: var(--radius);
}

/* ── Textareas / Code editor ─────────────────────────────────── */
.code-textarea {
  width: 100%;
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  line-height: 1.6;
  padding: 0.85rem 1rem;
  resize: vertical;
  outline: none;
  tab-size: 4;
  transition: border-color var(--transition), box-shadow var(--transition);
  caret-color: var(--accent);
}

.code-textarea::placeholder {
  color: var(--text-muted);
  opacity: 0.7;
}

.code-textarea:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.code-textarea--error {
  border-color: var(--red-border);
  background: var(--red-bg);
}

.code-textarea--error:focus {
  border-color: var(--red);
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.1);
}

/* Char/line counter row */
.textarea-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: -0.35rem;
}

.analyze-row {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  flex-wrap: wrap;
  padding-top: 0.1rem;
}

/* ── Workflow Status ─────────────────────────────────────────── */
.workflow-status {
  display: flex;
  align-items: center;
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 0.85rem 1.5rem;
  overflow-x: auto;
  scrollbar-width: none;
  gap: 0;
  box-shadow: var(--shadow-sm);
}

.workflow-status::-webkit-scrollbar { display: none; }

/* Pipeline label */
.workflow-status-label {
  font-size: 0.62rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  white-space: nowrap;
  margin-right: 1.25rem;
  padding-right: 1.25rem;
  border-right: 1px solid var(--border);
  flex-shrink: 0;
}

.workflow-step {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}

.workflow-node {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.67rem;
  font-weight: 700;
  border: 2px solid var(--border);
  color: var(--text-muted);
  background: var(--bg-surface);
  flex-shrink: 0;
  transition: all var(--transition);
  position: relative;
  z-index: 1;
}

.workflow-label {
  font-size: 0.73rem;
  color: var(--text-muted);
  white-space: nowrap;
  transition: color var(--transition);
  font-weight: 500;
}

.workflow-connector {
  flex: 1;
  min-width: 24px;
  max-width: 48px;
  height: 2px;
  margin: 0 0.3rem;
  border-radius: 1px;
  flex-shrink: 0;
  transition: background var(--transition);
}

.workflow-connector--pending {
  background: repeating-linear-gradient(
    to right,
    var(--border) 0px,
    var(--border) 3px,
    transparent 3px,
    transparent 7px
  );
}

.workflow-connector--done {
  background: var(--green);
}

/* Active step */
.workflow-step--active .workflow-node {
  border-color: var(--accent);
  background: var(--accent-light);
  color: var(--accent);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}
.workflow-step--active .workflow-label {
  color: var(--accent);
  font-weight: 700;
}

/* Done step */
.workflow-step--done .workflow-node {
  border-color: var(--green);
  background: var(--green-bg);
  color: var(--green);
}
.workflow-step--done .workflow-label {
  color: var(--green);
}

/* ── Analysis Panel ──────────────────────────────────────────── */
.analysis-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

@media (max-width: 600px) {
  .analysis-grid { grid-template-columns: 1fr; }
}

.analysis-field {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.65rem 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  transition: border-color var(--transition);
}

.analysis-field:hover { border-color: var(--border); }

.analysis-field--wide {
  grid-column: 1 / -1;
}

.field--highlight {
  border-color: var(--accent-border);
  background: var(--accent-light);
}

.field--highlight:hover { border-color: #93c5fd; }

.field-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 600;
}

.field-value {
  font-size: 0.87rem;
  color: var(--text);
  word-break: break-word;
  line-height: 1.5;
}

.field-value--mono {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  color: var(--accent-dark);
}

/* Confidence badge */
.confidence-badge {
  font-size: 0.71rem;
  font-weight: 700;
  padding: 0.22rem 0.65rem;
  border-radius: var(--radius);
  letter-spacing: 0.02em;
}

.confidence--high   { background: var(--green-bg);   color: var(--green);  border: 1px solid var(--green-border); }
.confidence--medium { background: var(--yellow-bg);  color: var(--yellow); border: 1px solid var(--yellow-border); }
.confidence--low    { background: var(--red-bg);     color: var(--red);    border: 1px solid var(--red-border); }

/* ── Fix Panel ───────────────────────────────────────────────── */
.fix-explanation,
.fix-proposed-change {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.85rem 1rem;
}

.subsection-title {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 700;
  margin-bottom: 0.4rem;
}

.explanation-text {
  font-size: 0.87rem;
  color: var(--text);
  line-height: 1.65;
}

/* Code tabs */
.code-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
  background: var(--bg-surface);
  border-radius: var(--radius) var(--radius) 0 0;
  padding: 0 0.25rem;
}

.code-tab {
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  font-family: var(--font-sans);
  transition: color var(--transition), border-color var(--transition);
  margin-bottom: -1px;
}

.code-tab:hover { color: var(--text); }

.code-tab--active {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-weight: 700;
}

/* Code blocks */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  line-height: 1.6;
  overflow-x: auto;
  white-space: pre;
  color: var(--text);
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

.code-block::-webkit-scrollbar { height: 5px; }
.code-block::-webkit-scrollbar-track { background: transparent; }
.code-block::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

/* When tabs precede a code block, square the top corners */
.code-tabs + .code-block {
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}

.code-block--compact   { font-size: 0.77rem; padding: 0.75rem 0.9rem; }
.code-block--fixed     { border-color: var(--green-border); }
.code-block--stderr    { color: var(--red); }

/* Diff colouring */
.diff-add    { display: block; background: var(--diff-add-bg); color: var(--green); }
.diff-remove { display: block; background: var(--diff-del-bg); color: var(--red); }
.diff-hunk   { display: block; color: var(--diff-hunk); opacity: 0.75; }

.applied-notice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Test Results ────────────────────────────────────────────── */
.test-results {
  border-top: 1px solid var(--border-subtle);
  padding-top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.test-summary-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.test-status-badge {
  font-size: 0.78rem;
  font-weight: 700;
  padding: 0.28rem 0.8rem;
  border-radius: var(--radius);
  letter-spacing: 0.04em;
}

.test-status-badge--pass {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid var(--green-border);
}

.test-status-badge--fail {
  background: var(--red-bg);
  color: var(--red);
  border: 1px solid var(--red-border);
}

.test-counts {
  font-size: 0.82rem;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.tests-passed { color: var(--green); font-weight: 600; }
.tests-failed { color: var(--red);   font-weight: 600; }
.tests-errors { color: var(--yellow); font-weight: 600; }

.return-code {
  font-size: 0.73rem;
  color: var(--text-muted);
  font-family: var(--font-mono);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  padding: 0.18rem 0.5rem;
  border-radius: 4px;
  margin-left: auto;
}

.test-output {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.output-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 700;
  margin-bottom: 0.15rem;
}

/* ── Badges ─────────────────────────────────────────────────── */
.badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 0.2rem 0.6rem;
  border-radius: var(--radius);
  letter-spacing: 0.02em;
}

.badge--green  { background: var(--green-bg);  color: var(--green);  border: 1px solid var(--green-border); }
.badge--yellow { background: var(--yellow-bg); color: var(--yellow); border: 1px solid var(--yellow-border); }

