.analysis-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

@media (max-width: 600px) {
  .analysis-grid { grid-template-columns: 1fr; }
}

.analysis-field {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.65rem 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  transition: border-color var(--transition);
}

.analysis-field:hover { border-color: var(--border); }

.analysis-field--wide {
  grid-column: 1 / -1;
}

.field--highlight {
  border-color: var(--accent-border);
  background: var(--accent-light);
}

.field--highlight:hover { border-color: #93c5fd; }

.field-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 600;
}

.field-value {
  font-size: 0.87rem;
  color: var(--text);
  word-break: break-word;
  line-height: 1.5;
}

.field-value--mono {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  color: var(--accent-dark);
}

/* Confidence badge */
.confidence-badge {
  font-size: 0.71rem;
  font-weight: 700;
  padding: 0.22rem 0.65rem;
  border-radius: var(--radius);
  letter-spacing: 0.02em;
}

.confidence--high   { background: var(--green-bg);   color: var(--green);  border: 1px solid var(--green-border); }
.confidence--medium { background: var(--yellow-bg);  color: var(--yellow); border: 1px solid var(--yellow-border); }
.confidence--low    { background: var(--red-bg);     color: var(--red);    border: 1px solid var(--red-border); }

/* ── Fix Panel ───────────────────────────────────────────────── */
.fix-explanation,
.fix-proposed-change {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.85rem 1rem;
}

.subsection-title {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 700;
  margin-bottom: 0.4rem;
}

.explanation-text {
  font-size: 0.87rem;
  color: var(--text);
  line-height: 1.65;
}

/* Code tabs */
.code-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
  background: var(--bg-surface);
  border-radius: var(--radius) var(--radius) 0 0;
  padding: 0 0.25rem;
}

.code-tab {
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  font-family: var(--font-sans);
  transition: color var(--transition), border-color var(--transition);
  margin-bottom: -1px;
}

.code-tab:hover { color: var(--text); }

.code-tab--active {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-weight: 700;
}

/* Code blocks */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  line-height: 1.6;
  overflow-x: auto;
  white-space: pre;
  color: var(--text);
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

.code-block::-webkit-scrollbar { height: 5px; }
.code-block::-webkit-scrollbar-track { background: transparent; }
.code-block::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

/* When tabs precede a code block, square the top corners */
.code-tabs + .code-block {
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}

.code-block--compact   { font-size: 0.77rem; padding: 0.75rem 0.9rem; }
.code-block--fixed     { border-color: var(--green-border); }
.code-block--stderr    { color: var(--red); }

/* Diff colouring */
.diff-add    { display: block; background: var(--diff-add-bg); color: var(--green); }
.diff-remove { display: block; background: var(--diff-del-bg); color: var(--red); }
.diff-hunk   { display: block; color: var(--diff-hunk); opacity: 0.75; }

.applied-notice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Test Results ────────────────────────────────────────────── */
.test-results {
  border-top: 1px solid var(--border-subtle);
  padding-top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.test-summary-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.test-status-badge {
  font-size: 0.78rem;
  font-weight: 700;
  padding: 0.28rem 0.8rem;
  border-radius: var(--radius);
  letter-spacing: 0.04em;
}

.test-status-badge--pass {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid var(--green-border);
}

.test-status-badge--fail {
  background: var(--red-bg);
  color: var(--red);
  border: 1px solid var(--red-border);
}

.test-counts {
  font-size: 0.82rem;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.tests-passed { color: var(--green); font-weight: 600; }
.tests-failed { color: var(--red);   font-weight: 600; }
.tests-errors { color: var(--yellow); font-weight: 600; }

.return-code {
  font-size: 0.73rem;
  color: var(--text-muted);
  font-family: var(--font-mono);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  padding: 0.18rem 0.5rem;
  border-radius: 4px;
  margin-left: auto;
}

.test-output {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.output-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 700;
  margin-bottom: 0.15rem;
}

/* ── Badges ─────────────────────────────────────────────────── */
.badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 0.2rem 0.6rem;
  border-radius: var(--radius);
  letter-spacing: 0.02em;
}

.badge--green  { background: var(--green-bg);  color: var(--green);  border: 1px solid var(--green-border); }
.badge--yellow { background: var(--yellow-bg); color: var(--yellow); border: 1px solid var(--yellow-border); }

/* ── Divider label ───────────────────────────────────────────── */
.section-divider {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-muted);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
}
.section-divider::before,
.section-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

/* ── Banners ─────────────────────────────────────────────────── */
.error-banner {
  background: var(--red-bg);
  border: 1px solid var(--red-border);
  border-radius: var(--radius);
  color: var(--red);
  font-size: 0.85rem;
  padding: 0.7rem 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  animation: slideDown 0.15s ease;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.error-banner strong { flex-shrink: 0; }

.error-banner-close {
  margin-left: auto;
  background: none;
  border: none;
  color: var(--red);
  cursor: pointer;
  font-size: 0.85rem;
  padding: 0.15rem 0.4rem;
  border-radius: 3px;
  flex-shrink: 0;
  transition: background var(--transition);
}
.error-banner-close:hover { background: rgba(220, 38, 38, 0.1); }

.warn-banner {
  background: var(--yellow-bg);
  border: 1px solid var(--yellow-border);
  border-radius: var(--radius);
  color: var(--yellow);
  font-size: 0.82rem;
  padding: 0.65rem 1rem;
}

.warn-banner code {
  background: rgba(180, 83, 9, 0.08);
  padding: 0.1rem 0.4rem;
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: 0.8em;
}

/* ── Info box ────────────────────────────────────────────────── */
.info-box--warning {
  background: var(--yellow-bg);
  border: 1px solid var(--yellow-border);
  border-radius: var(--radius);
  color: var(--yellow);
  font-size: 0.82rem;
  padding: 0.65rem 1rem;
}

/* ── Footer ─────────────────────────────────────────────────── */
.app-footer {
  text-align: center;
  font-size: 0.72rem;
  color: var(--text-muted);
  padding: 1.5rem 1rem;
  border-top: 1px solid var(--border-subtle);
  letter-spacing: 0.02em;
}

